mapper.select:
SELECT p.MON_UPRC AS "monthlyPrice" FROM TB_HR_DEV_PRC p WHERE p.DEV_ID=#{id}
  AND p.APLY_BGN_YM <= #{month} AND (p.APLY_END_YM IS NULL OR p.APLY_END_YM >= #{month})
ORDER BY p.APLY_BGN_YM DESC LIMIT 1

 WHERE l.RCMD_TYPE_CD='AI'
  AND CASE WHEN left(l.SCORE_DTL,6)='{"v":1' THEN l.SCORE_DTL::jsonb->>'f' ELSE NULL END=#{fingerprint}
ORDER BY l.RCMD_ID,l.RANK_ORD

mapper.update:
UPDATE TB_SL_RCMD_LOG SET USER_ACT_CD=#{action},ACT_USER_ID=#{actor},ACT_DTTM=clock_timestamp()
  ,NEED_SN=#{needSn}
WHERE RCMD_ID=CAST(#{recommendationId} AS numeric) AND DEV_ID=#{developerId} AND RCMD_TYPE_CD='AI'

UPDATE TB_SL_RCMD_LOG SET USER_ACT_CD='EXCL',RCMD_EXCL_CD=#{action.reasonCode},
  ACT_USER_ID=#{action.actor},ACT_DTTM=clock_timestamp(),SCORE_DTL=#{scoreDetail}
WHERE RCMD_ID=CAST(#{action.recommendationId} AS numeric) AND DEV_ID=#{action.developerId} AND RCMD_TYPE_CD='AI'
